// Verify a project generated by create-module-federation (see tests/core/fixture-tooling.ts):
// it must be self-consistent, resolve its Module Federation packages from the overridden
// builds, build with its own `build` script, and emit a federated remote.
//   node scripts/verify-scaffold.mjs <project dir> <mf name>
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'

const [dirArg, mfName] = process.argv.slice(2)
assert.ok(dirArg && mfName, 'usage: verify-scaffold.mjs <dir> <mf name>')
const dir = path.resolve(dirArg)
const label = path.basename(dir)
const pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf-8'))
const declared = { ...pkg.dependencies, ...pkg.devDependencies }

assert.equal(pkg.name, mfName, `${label}: --name was not applied to package.json`)

// The template bakes the generator's own version into its @module-federation/* ranges.
const mfDeps = Object.entries(declared).filter(([name]) => name.startsWith('@module-federation/'))
assert.ok(mfDeps.length > 0, `${label}: generated package.json has no @module-federation/* dependency`)
for (const [name, range] of mfDeps) {
	assert.match(range, /^\^\d+\.\d+\.\d+/, `${label}: ${name} has unrendered range "${range}"`)
	const installed = path.join(dir, 'node_modules', name, 'package.json')
	assert.ok(fs.existsSync(installed), `${label}: ${name} is not installed`)
}

// Every package the generated config files import must be declared, or the project cannot build.
const configs = fs.readdirSync(dir).filter((f) => /\.config\.(c|m)?[jt]s$/.test(f))
assert.ok(configs.length > 0, `${label}: no config files generated`)
for (const file of configs) {
	const source = fs.readFileSync(path.join(dir, file), 'utf-8')
	for (const [, spec] of source.matchAll(/from\s+['"]([^'"./][^'"]*)['"]/g)) {
		const name = spec.startsWith('@') ? spec.split('/').slice(0, 2).join('/') : spec.split('/')[0]
		assert.ok(
			declared[name],
			`${label}: ${file} imports "${spec}" but the generated package.json does not depend on ${name} ` +
				`(declares: ${Object.keys(declared).join(', ')})`,
		)
	}
}

console.log(`${label}: pnpm run build`)
const build = spawnSync('pnpm', ['run', 'build'], { cwd: dir, stdio: 'inherit' })
assert.equal(build.status, 0, `${label}: pnpm run build failed`)

// A federated build writes mf-manifest.json (dist/ for apps, dist/mf/ for rslib libraries).
const manifestFile = ['dist/mf-manifest.json', 'dist/mf/mf-manifest.json']
	.map((f) => path.join(dir, f))
	.find((f) => fs.existsSync(f))
assert.ok(manifestFile, `${label}: build emitted no mf-manifest.json`)
const manifest = JSON.parse(fs.readFileSync(manifestFile, 'utf-8'))
assert.equal(manifest.name, mfName, `${label}: manifest name`)
assert.ok(
	manifest.exposes?.some((e) => e.path === '.' || e.name === '.'),
	`${label}: manifest does not expose "."`,
)
// Everything the manifest advertises to consumers must have been emitted: the container, and
// the types archive + API types a host's dts plugin / `mf dts` downloads (metaData.types).
const outDir = path.dirname(manifestFile)
const { remoteEntry, types } = manifest.metaData ?? {}
assert.ok(remoteEntry?.name, `${label}: manifest has no remoteEntry`)
const advertised = [path.join(remoteEntry.path ?? '', remoteEntry.name)]
for (const key of ['zip', 'api']) {
	if (types?.[key]) advertised.push(path.join(types.path ?? '', types[key]))
}
const missing = advertised.filter((f) => !fs.existsSync(path.join(outDir, f)))
assert.deepEqual(
	missing,
	[],
	`${label}: mf-manifest.json advertises files the build did not emit: ${missing.join(', ')} ` +
		'(for types, look for "Failed to generate type declaration" / TYPE-001 in the build output above)',
)
console.log(`${label}: generated project builds a federated remote (${advertised.join(', ')})`)
